    private $handle;
    private $ids;

    public function __destruct()
    {
        if (isset($this->handle)) {
            fclose($this->handle);
        }
    }

    public function getMeta()
    {
        return self::META;
    }

    public function get($id)
    {
        if (!isset(self::OFFSETS[$id])) {
            return null;
        }

        return $this->decode(json_decode($this->read(__COMPILER_HALT_OFFSET__ + 1 + self::OFFSETS[$id]), true));
    }

    private function decode($compact)
    {
        $doc = $this->decodeBody($compact[0], $compact[1]);

        if (!empty($compact[2] ?? null)) {
            $doc['params'] = array_map([$this, 'decodeParam'], $compact[2]);
        }

        if (!empty($compact[3] ?? null)) {
            $doc['return'] = $this->decodeBody($compact[3][0], $compact[3][1]);
        }

        if (!empty($compact[4] ?? null)) {
            $doc['seeAlso'] = $compact[4];
        }

        return $doc;
    }

    private function decodeParam(array $param)
    {
        return ['name' => $param[0]] + $this->decodeBody($param[1], $param[2]);
    }

    private function decodeBody($type, $body)
    {
        if (is_string($body)) {
            return [
                'type' => $type,
                'description' => $body,
            ];
        }

        [$content, $description] = $this->inflateAndFlattenContent($body);

        return [
            'type' => $type,
            'description' => $description,
            'content' => $content,
        ];
    }

    private function inflateAndFlattenContent(array $body)
    {
        $content = [];
        $parts = [];

        foreach ($body as $block) {
            if (is_string($block)) {
                $block = [
                    'type' => 'paragraph',
                    'text' => $block,
                ];
            }

            $content[] = $block;

            $text = $this->flattenBlock($block);
            if ($text !== '') {
                $parts[] = $text;
            }
        }

        return [$content, implode("\n\n", $parts)];
    }

    private function flattenBlock(array $block)
    {
        if (($block['type'] ?? null) === 'table') {
            $parts = [];

            if (!empty($block['title'])) {
                $parts[] = $block['title'];
            }

            if (!empty($block['headers'])) {
                $parts[] = implode(' | ', $block['headers']);
            }

            foreach (($block['rows'] ?? []) as $row) {
                $parts[] = implode(' | ', $row);
            }

            return implode("\n", array_filter($parts, 'strlen'));
        }

        return $block['text'] ?? '';
    }

    public function has($id)
    {
        return isset(self::OFFSETS[$id]);
    }

    private function read($offset, $length = null)
    {
        if (!isset($this->handle)) {
            $this->handle = fopen(__FILE__, 'r');
        }

        fseek($this->handle, $offset);

        return $length === null ? fgets($this->handle) : fread($this->handle, $length);
    }

    public function getIds()
    {
        if (!isset($this->ids)) {
            $this->ids = array_keys(self::OFFSETS);
        }

        return $this->ids;
    }
};

