["function","Annotates an image with text\n\nAnnotates an image with text.",[["$draw_settings","ImagickDraw","The ImagickDraw object that contains settings for drawing the text"],["$x","float","Horizontal offset in pixels to the left of text"],["$y","float","Vertical offset in pixels to the baseline of text"],["$angle","float","The angle at which to write the text"],["$text","string","The string to draw"]],["bool","Returns <type>true<\/type> on success."],["<function>ImagickDraw::annotation<\/function>","<function>ImagickDraw::setFont<\/function>"]]
