["function","Verify embedded or cleartext signatures",[["$ffi","RnpFFI","The FFI object returned by <function>rnp_ffi_create<\/function>."],["$data","string","Signed data."]],["array|false",["An associative array with information about verification results or <type>false<\/type> on failure.",{"type":"table","title":"","headers":["Key","Data type","Description"],"rows":[["<literal>\"verification_status\"<\/literal>","string","Overall verification result, either \"Success\" string or appropriate error message. \"Success\" result is set when at least one signature is valid and successfully verified. Individual verification results for each signature can be checked in the \"signatures\" array."],["<literal>\"file_name\"<\/literal>","string","File name."],["<literal>\"file_mtime\"<\/literal>","integer","File modification time."],["<literal>\"mode\"<\/literal>","string","Data protection (encryption) mode used in processed message. Currently defined values are \"none\", \"cfb\", \"cfb-mdc\", \"aead-ocb\", \"aead-eax\"."],["<literal>\"cipher\"<\/literal>","string","Symmetric cipher used for data encryption."],["<literal>\"valid_integrity\"<\/literal>","boolean","<type>true<\/type> if message integrity protection was used (i.e. MDC or AEAD) and it was validated successfully."],["<literal>\"signatures\"<\/literal>","array","An associative array describing each signature found. See description below."]]},"\"signatures\" sub-array.",{"type":"table","title":"","headers":["Key","Data type","Description"],"rows":[["\"verification_status\"","string","Signature verification status, either \"Success\" string or appropriate error message."],["\"creation_time\"","integer","Signature creation time in seconds since Jan, 1 1970 UTC."],["\"expiration_time\"","integer","Signature expiration time in seconds since the creation time or 0 if signature never expires."],["\"hash\"","string","Hash function algorithm used to calculate the signature."],["\"signing_key\"","string","Fingerprint of the key used for signing. Could be \"Not found\" if corresponding public key is not loaded to the FFI object."],["\"signature_type\"","string","Signature type. Currently defined values are: 'binary', 'text', 'standalone', 'certification (generic)', 'certification (persona)', 'certification (casual)', 'certification (positive)', 'subkey binding', 'primary key binding', 'direct', 'key revocation', 'subkey revocation', 'certification revocation', 'timestamp', 'uknown: 0..255'."]]}]]]
["function","Verify detached signatures",[["$ffi","RnpFFI","The FFI object returned by <function>rnp_ffi_create<\/function>."],["$data","string","Source data."],["$signature","string","Detached signature data."]],["array|false",["An associative array with information about verification results or <type>false<\/type> on failure.",{"type":"table","title":"","headers":["Key","Data type","Description"],"rows":[["<literal>\"verification_status\"<\/literal>","string","Overall verification result, either \"Success\" string or appropriate error message. \"Success\" result is set when at least one signature is valid and successfully verified. Individual verification results for each signature can be checked in the \"signatures\" array."],["<literal>\"file_name\"<\/literal>","string","File name."],["<literal>\"file_mtime\"<\/literal>","integer","File modification time."],["<literal>\"mode\"<\/literal>","string","Data protection (encryption) mode used in processed message. Currently defined values are \"none\", \"cfb\", \"cfb-mdc\", \"aead-ocb\", \"aead-eax\"."],["<literal>\"cipher\"<\/literal>","string","Symmetric cipher used for data encryption."],["<literal>\"valid_integrity\"<\/literal>","boolean","<type>true<\/type> if message integrity protection was used (i.e. MDC or AEAD) and it was validated successfully."],["<literal>\"signatures\"<\/literal>","array","An associative array describing each signature found. See description below."]]},"\"signatures\" sub-array.",{"type":"table","title":"","headers":["Key","Data type","Description"],"rows":[["\"verification_status\"","string","Signature verification status, either \"Success\" string or appropriate error message."],["\"creation_time\"","integer","Signature creation time in seconds since Jan, 1 1970 UTC."],["\"expiration_time\"","integer","Signature expiration time in seconds since the creation time or 0 if signature never expires."],["\"hash\"","string","Hash function algorithm used to calculate the signature."],["\"signing_key\"","string","Fingerprint of the key used for signing. Could be \"Not found\" if corresponding public key is not loaded to the FFI object."],["\"signature_type\"","string","Signature type. Currently defined values are: 'binary', 'text', 'standalone', 'certification (generic)', 'certification (persona)', 'certification (casual)', 'certification (positive)', 'subkey binding', 'primary key binding', 'direct', 'key revocation', 'subkey revocation', 'certification revocation', 'timestamp', 'uknown: 0..255'."]]}]]]
