["function","Add a new function, similar to create_function",[["$function_name","string","Name of the function to be created"],["$argument_list","string","Comma separated argument list"],["$code","string","Code making up the function"],["$closure","Closure","A <classname>closure<\/classname> that defines the function."],["$return_by_reference","bool","Whether the function should return by reference."],["$doc_comment","string","The doc comment of the function."],["$return_type","string","The return type of the function."],["$is_strict","bool","Whether the function should behave as if it were declared in a file with <literal>strict_types=1<\/literal>"]],["bool","Returns <type>true<\/type> on success or <type>false<\/type> on failure."],["<function>create_function<\/function>","<function>runkit7_function_redefine<\/function>","<function>runkit7_function_copy<\/function>","<function>runkit7_function_rename<\/function>","<function>runkit7_function_remove<\/function>","<function>runkit7_method_add<\/function>"]]
